import React from 'react';
import { useTranslation } from 'react-i18next';
import { useQuery } from '@tanstack/react-query';
import axiosInstance from '../core/api/axiosConfig';
import { Box, Typography, Paper, Grid, Card, CardContent, CircularProgress } from '@mui/material';

const ReportItem = ({ title, value }) => (
  <Grid item xs={12} sm={6} md={4}>
    <Card><CardContent><Typography variant="body2" color="textSecondary">{title}</Typography><Typography variant="h5">{value || '—'}</Typography></CardContent></Card>
  </Grid>
);

const ReportsPage = () => {
  const { t } = useTranslation();

  const { data: byDept } = useQuery({ queryKey: ['report-dept'], queryFn: () => axiosInstance.get('/reports/employees-by-department/').then(r => r.data) });
  const { data: byGender } = useQuery({ queryKey: ['report-gender'], queryFn: () => axiosInstance.get('/reports/employees-by-gender/').then(r => r.data) });
  const { data: byLocation } = useQuery({ queryKey: ['report-loc'], queryFn: () => axiosInstance.get('/reports/employees-by-location/').then(r => r.data) });
  const { data: contracts } = useQuery({ queryKey: ['report-contracts'], queryFn: () => axiosInstance.get('/reports/contracts-expiring/').then(r => r.data) });
  const { data: turnover } = useQuery({ queryKey: ['report-turnover'], queryFn: () => axiosInstance.get('/reports/turnover-rate/').then(r => r.data) });

  return (
    <Box>
      <Typography variant="h4" gutterBottom>{t('reports.title')}</Typography>

      <Typography variant="h6" sx={{ mt: 2, mb: 1 }}>{t('reports.employees_by_department')}</Typography>
      <Paper sx={{ p: 2, mb: 2 }}>
        {byDept ? byDept.map((d, i) => <Typography key={i} variant="body2">{d.name}: {d.count} ({d.percent}%)</Typography>) : <CircularProgress size={20} />}
      </Paper>

      <Typography variant="h6" sx={{ mt: 2, mb: 1 }}>{t('reports.employees_by_gender')}</Typography>
      <Grid container spacing={2} sx={{ mb: 2 }}>
        {byGender ? byGender.map((g, i) => <ReportItem key={i} title={g.gender} value={`${g.count} (${g.percent}%)`} />) : <CircularProgress size={20} />}
      </Grid>

      <Typography variant="h6" sx={{ mt: 2, mb: 1 }}>{t('reports.employees_by_location')}</Typography>
      <Paper sx={{ p: 2, mb: 2 }}>
        {byLocation ? byLocation.map((l, i) => <Typography key={i} variant="body2">{l.name}: {l.count}</Typography>) : <CircularProgress size={20} />}
      </Paper>

      <Typography variant="h6" sx={{ mt: 2, mb: 1 }}>{t('reports.contracts_expiring')}</Typography>
      <Paper sx={{ p: 2, mb: 2 }}>
        {contracts?.length === 0 ? <Typography>{t('common.noData')}</Typography> : contracts?.map((c, i) => <Typography key={i} variant="body2">{c.full_name} ({c.employee_id}) - {c.contract_end_date}</Typography>)}
      </Paper>

      <Typography variant="h6" sx={{ mt: 2, mb: 1 }}>{t('reports.turnover_rate')}</Typography>
      <Paper sx={{ p: 2, mb: 2 }}>
        {turnover ? <Typography variant="h5">{turnover.rate}%</Typography> : <CircularProgress size={20} />}
      </Paper>
    </Box>
  );
};

export default ReportsPage;
